#[test]
fn signbit_f64() {
    let _report = Report;
    const CASES: &[(f64, bool)] = &[
        (f64::NAN, false),
        (f64::INFINITY, false),
        (f64::NEG_INFINITY, true),
        (0.0, false),
        (-0.0, true),
        (1.0, false),
        (-1.0, true),
        (0.5, false),
        (-0.5, true),
        (1.5, false),
        (-1.5, true),
        (2.5, false),
        (-2.5, true),
        (3.0, false),
        (4.5, false),
        (-7.25, true),
        (8.0, false),
        (8.000001, false),
        (100.0, false),
        (123456.789, false),
        (1e+16, false),
        (0.1, false),
        (-0.1, true),
        (1e-300, false),
        (-1e-300, true),
        (5e-324, false),
        (-5e-324, true),
        (2.2250738585072014e-308, false),
        (1e+300, false),
        (-1e+300, true),
        (1.7976931348623157e+308, false),
        (-1.7976931348623157e+308, true),
    ];
    for &(x, want) in CASES {
        assert_eq!(signbit(x), want, "signbit({x:?})");
    }
    // a NaN with the sign bit set: NumPy says True
    assert!(signbit(f64::from_bits(0xFFF8_0000_0000_0000)));
    assert!(!signbit(f32::NAN));
    assert!(signbit(-0.0f32));
}
