#[test]
fn ediff1d_cases() {
    let _report = Report;
    {
        let a: &[i64] = &[1, 2, 4, 7, 11];
        let end: &[i64] = &[];
        let beg: &[i64] = &[];
        let want: &[i64] = &[1, 2, 3, 4];
        assert_eq!(ediff1d(a, end, beg), want, "ediff1d ints");
    }
    {
        let a: &[i64] = &[1, 2, 4, 7, 11];
        let end: &[i64] = &[99];
        let beg: &[i64] = &[-5, -6];
        let want: &[i64] = &[-5, -6, 1, 2, 3, 4, 99];
        assert_eq!(ediff1d(a, end, beg), want, "ediff1d ints_end_begin");
    }
    {
        let a: &[f64] = &[1.5, 1.0, 3.25, -2.0];
        let end: &[f64] = &[];
        let beg: &[f64] = &[];
        let want: &[f64] = &[-0.5, 2.25, -5.25];
        assert_eq!(ediff1d(a, end, beg), want, "ediff1d floats");
    }
    {
        let a: &[f64] = &[1.5, 1.0, 3.25, -2.0];
        let end: &[f64] = &[0.5, 0.25];
        let beg: &[f64] = &[];
        let want: &[f64] = &[-0.5, 2.25, -5.25, 0.5, 0.25];
        assert_eq!(ediff1d(a, end, beg), want, "ediff1d floats_end");
    }
    {
        let a: &[f64] = &[4.0];
        let end: &[f64] = &[];
        let beg: &[f64] = &[];
        let want: &[f64] = &[];
        assert_eq!(ediff1d(a, end, beg), want, "ediff1d single");
    }
    {
        let a: &[f64] = &[];
        let end: &[f64] = &[1.0];
        let beg: &[f64] = &[2.0];
        let want: &[f64] = &[2.0, 1.0];
        assert_eq!(ediff1d(a, end, beg), want, "ediff1d empty");
    }
}
